+/// Downloads the raw message, failing on a non success status so that an error page is never
+/// forwarded as if it were the original email.
+#[maybe_async::maybe_async]
+async fn download_raw(url: String) -> Result<Vec<u8>> {
+    Ok(reqwest::get(url)
+        .await?
+        .error_for_status()?
+        .bytes()
+        .await?
+        .to_vec())
+}
